replacement="function teacherNotesPage(allowedClassIds){\n const classes=data.classes.filter(c=>!c.archived&&allowedClassIds.includes(c.id))\n  .sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'fr'));\n if(!classes.length){shell(title('Notes','Tableau par classe')+'<div class=\"card\">Aucune classe affectée.</div>');return}\n if(!classes.some(c=>c.id===teacherNotesSelectedClass))teacherNotesSelectedClass=classes[0].id;\n const chosen=classes.find(c=>c.id===teacherNotesSelectedClass);\n const pupils=data.students.filter(st=>!st.archived&&st.classId===chosen.id)\n  .sort((a,b)=>String(a.last||'').localeCompare(String(b.last||''),'fr')||String(a.first||'').localeCompare(String(b.first||''),'fr'));\n const pupilIds=new Set(pupils.map(st=>st.id));\n const resultIds=new Set((data.results||[]).filter(r=>pupilIds.has(r.student)).map(r=>r.eval));\n const gradeIds=new Set((data.evalGrades||[]).filter(g=>pupilIds.has(g.studentId)).map(g=>g.evalId));\n const refKey=classReferentialKey(chosen);\n const candidates=data.evals.filter(ev=>evalReferentialKey(ev)===refKey&&\n  ((ev.classes||[]).includes(chosen.id)||resultIds.has(ev.id)||gradeIds.has(ev.id)))\n  .sort((a,b)=>String(a.date||'').localeCompare(String(b.date||''),'fr')||String(a.title||'').localeCompare(String(b.title||''),'fr'));\n const valid=n=>n!==null&&n!==undefined&&Number.isFinite(Number(n));\n const gradeMap=new Map(candidates.map(ev=>[ev.id,new Map(pupils.map(st=>[st.id,effectiveEvalGrade(ev.id,st.id)]))]));\n const assessments=candidates.filter(ev=>pupils.some(st=>valid(gradeMap.get(ev.id).get(st.id))));\n const stored=(data.teacherNotesSemesterCutoffs||{})[String(chosen.id)];\n let cut=stored&&stored.firstS2Id?assessments.findIndex(ev=>String(ev.id)===String(stored.firstS2Id)):-1;\n if(cut<0&&stored&&Number.isInteger(stored.index))cut=Math.max(0,Math.min(assessments.length,stored.index));\n if(cut<0){\n  const oldFirstS2=assessments.findIndex(ev=>(data.teacherNotesSemesters||{})[JSON.stringify([chosen.id,ev.id])]===2);\n  cut=oldFirstS2>=0?oldFirstS2:Math.ceil(assessments.length/2);\n }\n const left=assessments.slice(0,cut),right=assessments.slice(cut);\n const grade=(st,ev)=>gradeMap.get(ev.id).get(st.id);\n const cell=(st,ev)=>{\n  const n=grade(st,ev);\n  return valid(n)?'<span title=\"'+esc(evalGradeSourceLabel(ev.id,st.id))+'\">'+esc(formatGrade(n))+'</span>':'<span class=\"muted\">—</span>';\n };\n const mean=(st,evals)=>{\n  const values=evals.map(ev=>grade(st,ev)).filter(valid).map(Number);\n  return values.length?(values.reduce((a,b)=>a+b,0)/values.length).toLocaleString('fr-FR',{maximumFractionDigits:2})+' / 20':'—';\n };\n const head=ev=>'<th data-notes-eval-head=\"'+esc(ev.id)+'\" title=\"'+esc(ev.title||'Évaluation')+'\" style=\"width:72px;min-width:72px;max-width:72px;padding:6px;background:var(--panel);position:sticky;top:0;vertical-align:bottom;text-align:center\">'+\n  '<div data-notes-heading-vertical-v239=\"1\" style=\"writing-mode:vertical-rl;transform:rotate(180deg);display:inline-block;height:185px;max-height:185px;overflow:hidden;text-align:left;white-space:nowrap\">'+esc(ev.title||'Évaluation')+'</div>'+\n  '<div class=\"muted small\">'+esc(ev.date||'')+'</div></th>';\n const markerHead='<th data-notes-cut=\"1\" tabindex=\"0\" role=\"slider\" aria-label=\"Séparation entre le semestre 1 et le semestre 2\" aria-valuemin=\"0\" aria-valuemax=\"'+assessments.length+'\" aria-valuenow=\"'+cut+'\" title=\"Glisser la barre pour déplacer la limite des semestres. Flèches gauche et droite possibles.\" style=\"width:18px;min-width:18px;max-width:18px;padding:0;background:var(--panel);position:sticky;top:0;cursor:ew-resize;touch-action:none;user-select:none;border-left:4px solid #e6a23c\"><span style=\"display:inline-block;color:#e6a23c;font-size:14px\">↔</span></th>';\n const markerCell='<td style=\"width:18px;min-width:18px;max-width:18px;padding:0;border-left:4px solid #e6a23c;background:transparent\"></td>';\n const table=assessments.length?\n  '<div id=\"notes-scroll-v240\" style=\"position:relative;overflow:auto;max-width:100%;border:1px solid var(--line);border-radius:10px\">'+\n  '<div id=\"notes-drag-guide-v240\" style=\"display:none;position:absolute;top:0;bottom:0;width:4px;background:#e6a23c;z-index:6;pointer-events:none\"></div>'+\n  '<table style=\"width:100%;border-spacing:0;min-width:580px\"><thead><tr>'+\n  '<th style=\"position:sticky;left:0;top:0;background:var(--panel);min-width:180px;padding:10px;z-index:3;text-align:left\">Élève</th>'+\n  left.map(head).join('')+markerHead+right.map(head).join('')+\n  '<th style=\"background:var(--panel);padding:10px;min-width:85px\">Moy. S1</th><th style=\"background:var(--panel);padding:10px;min-width:85px\">Moy. S2</th></tr></thead><tbody>'+\n  pupils.map(st=>'<tr><th style=\"position:sticky;left:0;background:var(--panel);text-align:left;padding:10px;z-index:1;white-space:nowrap\">'+esc(st.last||'')+' '+esc(st.first||'')+'</th>'+\n   left.map(ev=>'<td style=\"text-align:center;padding:8px;border-top:1px solid var(--line)\">'+cell(st,ev)+'</td>').join('')+\n   markerCell+\n   right.map(ev=>'<td style=\"text-align:center;padding:8px;border-top:1px solid var(--line)\">'+cell(st,ev)+'</td>').join('')+\n   '<td style=\"text-align:center;padding:8px;font-weight:700\">'+mean(st,left)+'</td>'+\n   '<td style=\"text-align:center;padding:8px;font-weight:700\">'+mean(st,right)+'</td></tr>').join('')+\n  '</tbody></table></div>':\n  '<div class=\"card muted\">Aucune note dans cette classe. Les évaluations apparaîtront dès qu’un élève aura une note.</div>';\n shell(title('Notes','Récapitulatif chronologique par classe')+\n  '<div class=\"card\" style=\"margin-bottom:14px\"><label for=\"teacherNotesClass\">Classe</label> <select id=\"teacherNotesClass\" class=\"input\">'+\n  classes.map(c=>'<option value=\"'+esc(c.id)+'\"'+(c.id===chosen.id?' selected':'')+'>'+esc(c.name)+'</option>').join('')+\n  '</select><p class=\"muted small\">'+pupils.length+' élève(s) · '+assessments.length+' évaluation(s) notée(s). <b>À gauche de la barre orange : semestre 1 ; à droite : semestre 2.</b> Déplacez la barre ↔ horizontalement pour ajuster la limite.</p></div>'+table);\n const selector=document.getElementById('teacherNotesClass');\n if(selector)selector.onchange=()=>{teacherNotesSelectedClass=selector.value;teacherNotesPage(allowedClassIds)};\n const handle=document.querySelector('[data-notes-cut]');\n const wrapper=document.getElementById('notes-scroll-v240');\n const guide=document.getElementById('notes-drag-guide-v240');\n if(!handle||!wrapper||!guide)return;\n const indexAt=clientX=>{\n  const headers=Array.from(wrapper.querySelectorAll('[data-notes-eval-head]'));\n  const idx=headers.findIndex(h=>clientX<h.getBoundingClientRect().left+h.getBoundingClientRect().width/2);\n  return idx<0?headers.length:idx;\n };\n const saveCut=next=>{\n  next=Math.max(0,Math.min(assessments.length,next));\n  if(next===cut)return;\n  data.teacherNotesSemesterCutoffs=data.teacherNotesSemesterCutoffs||{};\n  data.teacherNotesSemesterCutoffs[String(chosen.id)]={index:next,firstS2Id:assessments[next]?String(assessments[next].id):null};\n  save();\n  teacherNotesPage(allowedClassIds);\n };\n let dragStart=null;\n handle.addEventListener('pointerdown',e=>{\n  if(e.button!==0)return;\n  dragStart={id:e.pointerId,x:e.clientX};\n  handle.setPointerCapture(e.pointerId);\n  e.preventDefault();\n });\n handle.addEventListener('pointermove',e=>{\n  if(!dragStart||dragStart.id!==e.pointerId)return;\n  const rect=wrapper.getBoundingClientRect();\n  guide.style.left=(e.clientX-rect.left+wrapper.scrollLeft)+'px';\n  guide.style.display='block';\n });\n handle.addEventListener('pointerup',e=>{\n  if(!dragStart||dragStart.id!==e.pointerId)return;\n  const target=indexAt(e.clientX);\n  dragStart=null;\n  guide.style.display='none';\n  saveCut(target);\n });\n handle.addEventListener('pointercancel',()=>{dragStart=null;guide.style.display='none'});\n handle.addEventListener('keydown',e=>{\n  if(e.key==='ArrowLeft'||e.key==='ArrowRight'){\n   e.preventDefault();\n   saveCut(cut+(e.key==='ArrowLeft'?-1:1));\n  }\n });\n}\n"
